(7246713, 1125137, 115814, '<td valign="top">I really like the effect of color variation between the foreground and background. Nicely composed.</td>', 'I really like the effect of color variation between the foreground and background. Nicely composed.', '2014-08-02 14:44:55.000000', NULL, 1),
(7246714, 1125060, 147314, '<td valign="top">I think the B&amp;W was a wise choice. Really like this image, making a great connection to desert travelling and modern transport.</td>', 'I think the B&W was a wise choice. Really like this image, making a great connection to desert travelling and modern transport.', '2014-08-02 14:45:49.000000', NULL, 1),
(7246716, 1124588, 147314, '<td valign="top">Lovely light and background. Maybe you could have cropped it a bit from the right.</td>', 'Lovely light and background. Maybe you could have cropped it a bit from the right.', '2014-08-02 14:47:07.000000', NULL, 1),
(7246717, 1124554, 115814, '<td valign="top">Terrific light and exposure. I love the subtle color of the yellow flower bokeh behind the calf, although it does draw a bit of attention away from the subject. Terrific photo.</td>', 'Terrific light and exposure. I love the subtle color of the yellow flower bokeh behind the calf, although it does draw a bit of attention away from the subject. Terrific photo.', '2014-08-02 14:47:22.000000', NULL, 1),
(7246719, 1124152, 147314, '<td valign="top">Beautiful. Bump!</td>', 'Beautiful. Bump!', '2014-08-02 14:47:43.000000', NULL, 1),
(7246724, 1124989, 115814, '<td valign="top">Looking at/for mom, no doubt... Nice composition. Although it appears you worked to soften the harsh shadows, for me they are slightly distracting. Still a strong entry.</td>', 'Looking at/for mom, no doubt... Nice composition. Although it appears you worked to soften the harsh shadows, for me they are slightly distracting. Still a strong entry.', '2014-08-02 14:49:37.000000', NULL, 1),
(7246725, 1124143, 115814, '<td valign="top">Amazing. I had no idea this is what a day old parrot looks like. What an unusual color palette - both in the bird and the overall photo. I might have considered a slight desaturation of the green. Still a 7 from me.</td>', 'Amazing. I had no idea this is what a day old parrot looks like. What an unusual color palette - both in the bird and the overall photo. I might have considered a slight desaturation of the green. Still a 7 from me.', '2014-08-02 14:52:10.000000', NULL, 1),
(7246726, 1125168, 115814, '<td valign="top">Whoa. If that doesn''t scream "Don''t mess with the babies," I don''t know what does. Awesome.</td>', 'Whoa. If that doesn''t scream "Don''t mess with the babies," I don''t know what does. Awesome.', '2014-08-02 14:53:06.000000', NULL, 1),
(7246727, 1125038, 115814, '<td valign="top">Nice depiction of the balance between curiosity and insecurity. I can feel the stillness in his posture.</td>', 'Nice depiction of the balance between curiosity and insecurity. I can feel the stillness in his posture.', '2014-08-02 14:54:34.000000', NULL, 1);
